) VALUES (
    'history-of-snowboarding',
    '{"en": "History of Snowboarding: Counter-Culture Becomes Olympic Sport", "de": "Geschichte des Snowboardens: Gegenkultur wird olympischer Sport", "fr": "Histoire du snowboard : La contre-culture devient sport olympique", "it": "Storia dello snowboard: La controcultura diventa sport olimpico", "es": "Historia del snowboard: La contracultura se convierte en deporte olímpico", "pt": "História do snowboard: A contracultura se torna esporte olímpico", "nl": "Geschiedenis van snowboarden: Tegencultuur wordt olympische sport", "ar": "تاريخ التزلج على الثلج: الثقافة المضادة تصبح رياضة أولمبية", "ja": "スノーボードの歴史：カウンターカルチャーがオリンピック競技に", "zh": "Danbuxue Lishi: Fanchuantong Wenhua Chengwei Aolinpike Yundong", "ko": "스노보드의 역사: 반문화에서 올림픽 스포츠로"}'::jsonb,
    '{"en": "Snowboarding was born from surfing culture and skateboarding, bringing a rebellious spirit to the mountains. Once banned from most ski resorts, it''s now a winter sports centerpiece.", "de": "Snowboarden entstand aus der Surf- und Skateboardkultur und brachte rebellischen Geist in die Berge.", "fr": "Le snowboard est né de la culture du surf et du skateboard, apportant un esprit rebelle aux montagnes.", "it": "Lo snowboard è nato dalla cultura del surf e dello skateboard, portando uno spirito ribelle in montagna.", "es": "El snowboard nació de la cultura del surf y el skateboard, trayendo un espíritu rebelde a las montañas.", "pt": "O snowboard nasceu da cultura do surfe e do skate, trazendo um espírito rebelde às montanhas.", "nl": "Snowboarden ontstond uit de surf- en skateboardcultuur en bracht een rebelse geest naar de bergen.", "ar": "ولد التزلج على الثلج من ثقافة ركوب الأمواج والتزلج على الألواح، جالباً روحاً متمردة إلى الجبال", "ja": "スノーボードはサーフィン文化とスケートボードから生まれ、反逆的な精神を山にもたらしました。", "zh": "Danbuxue dansheng yu chonglang wenhua he huaban yundong, gei shanqu dailai panpan jingshen.", "ko": "스노보드는 서핑 문화와 스케이트보드에서 탄생하여 반항적인 정신을 산에 가져왔습니다."}'::jsonb,
    '{"en": "<p><a href=\"/snowboarding-guide/\">Snowboarding</a> transformed winter sports culture. What began as backyard inventions by surfers and skateboarders seeking snow alternatives became one of the world''s most popular action sports.</p><h2>Birth of the Snurfer</h2><p>The story begins in 1965 when Sherman Poppen of Michigan fastened two skis together and attached a rope for his daughter to hold while riding downhill. He called it the \"Snurfer\" (snow + surfer). Poppen licensed the design to a toy company, and over a million Snurfers were sold in the following years.</p><h2>Pioneers and Inventors</h2><p>In the 1970s, several inventors independently developed snowboard designs. Jake Burton Carpenter in Vermont and Tom Sims in California created boards with bindings and edges, transforming the toy into sporting equipment.</p><p>Burton founded his company in 1977, initially selling boards from his barn. Sims, already a skateboard legend, brought skateboard culture into snow sports. The two companies would drive snowboarding''s evolution.</p><h2>Banned from Resorts</h2><p>Throughout the 1980s, snowboarders faced hostility from the skiing establishment. Most ski resorts banned snowboarding entirely, viewing riders as dangerous and disrespectful. Snowboarders hiked to find terrain or rode at the few resorts that welcomed them.</p><p>This outsider status shaped snowboarding''s counter-cultural identity, with its own music, fashion, and attitude distinct from traditional skiing.</p><h2>Mainstream Acceptance</h2><p>By the early 1990s, resorts began accepting snowboarders as they recognized the sport''s popularity and commercial potential. The ban at major resorts lifted, and snowboard-specific terrain parks emerged.</p><p>The 1998 Winter Games in Nagano included snowboarding for the first time, with giant slalom and halfpipe events. Ross Rebagliati''s controversial gold medal kept the sport in headlines.</p><h2>Discipline Development</h2><p>Modern snowboarding features multiple disciplines:</p><p><strong>Halfpipe:</strong> Athletes perform tricks while riding between the walls of a U-shaped course.</p><p><strong>Slopestyle:</strong> Riders navigate courses with rails, jumps, and obstacles.</p><p><strong>Big Air:</strong> Single massive jump for the most spectacular tricks.</p><p><strong>Snowboard Cross:</strong> Multiple riders race head-to-head down a course with jumps and turns.</p><p><strong>Alpine/Parallel Giant Slalom:</strong> Racing through gates on carved turns.</p><h2>Legends of the Sport</h2><p>Shaun White became snowboarding''s global ambassador, winning multiple world titles and bringing unprecedented mainstream attention. Terje Haakonsen, Gretchen Bleiler, and Kelly Clark became legends. The sport continues producing iconic athletes.</p><h2>Cultural Impact</h2><p>Snowboarding changed more than just winter sports. Its fashion, music, and attitude influenced broader youth culture. The industry it created—from equipment to media to events—represents billions in economic activity.</p><p>From banned activity to cultural phenomenon, snowboarding''s journey reflects how youth movements can reshape established industries.</p>", "de": "<p><a href=\"/snowboarding-guide/\">Snowboarding</a> transformierte die Wintersportkultur. Was als Hinterhoferfindungen begann, wurde zu einer der beliebtesten Actionsportarten der Welt.</p><h2>Geburt des Snurfers</h2><p>Die Geschichte beginnt 1965, als Sherman Poppen aus Michigan zwei Skier zusammenband und ein Seil für seine Tochter befestigte.</p><h2>Von Skigebieten verbannt</h2><p>In den 1980ern wurden Snowboarder von den meisten Skigebieten verbannt. Dieser Außenseiterstatus prägte die gegenkulturelle Identität des Snowboardens.</p><h2>Legenden des Sports</h2><p>Shaun White wurde zum globalen Botschafter des Snowboardens.</p>", "fr": "<p>Le <a href=\"/snowboarding-guide/\">snowboard</a> a transformé la culture des sports d''hiver. Ce qui a commencé comme des inventions de jardin est devenu l''un des sports d''action les plus populaires au monde.</p><h2>Naissance du Snurfer</h2><p>L''histoire commence en 1965 quand Sherman Poppen du Michigan a attaché deux skis ensemble.</p><h2>Banni des stations</h2><p>Tout au long des années 1980, les snowboarders ont fait face à l''hostilité de l''établissement du ski.</p><h2>Légendes du sport</h2><p>Shaun White est devenu l''ambassadeur mondial du snowboard.</p>", "it": "<p>Lo <a href=\"/snowboarding-guide/\">snowboard</a> ha trasformato la cultura degli sport invernali. Quello che è iniziato come invenzioni casalinghe è diventato uno degli sport d''azione più popolari al mondo.</p><h2>Nascita dello Snurfer</h2><p>La storia inizia nel 1965 quando Sherman Poppen del Michigan legò insieme due sci.</p><h2>Banditi dalle stazioni</h2><p>Per tutti gli anni ''80, gli snowboarder hanno affrontato l''ostilità dell''establishment sciistico.</p>", "es": "<p>El <a href=\"/snowboarding-guide/\">snowboard</a> transformó la cultura de los deportes de invierno. Lo que comenzó como invenciones caseras se convirtió en uno de los deportes de acción más populares del mundo.</p>", "pt": "<p>O <a href=\"/snowboarding-guide/\">snowboard</a> transformou a cultura dos esportes de inverno. O que começou como invenções caseiras se tornou um dos esportes de ação mais populares do mundo.</p>", "nl": "<p><a href=\"/snowboarding-guide/\">Snowboarden</a> transformeerde de wintersprtcultuur. Wat begon als achtertuinuitvindingen werd een van de populairste actiesportsporten ter wereld.</p>", "ar": "<p>حول <a href=\"/snowboarding-guide/\">التزلج على الثلج</a> ثقافة الرياضات الشتوية. ما بدأ كاختراعات منزلية أصبح واحداً من أكثر الرياضات المتطرفة شعبية في العالم.</p>", "ja": "<p><a href=\"/snowboarding-guide/\">スノーボード</a>はウィンタースポーツ文化を変革しました。裏庭の発明として始まったものが、世界で最も人気のあるアクションスポーツの一つになりました。</p>", "zh": "<p><a href=\"/snowboarding-guide/\">Danbuxue</a> gaibian le dongji yundong wenhua. Cong houyuan faming kaishi, chengwei shijie shang zui liuxing de jixian yundong zhiyi.</p>", "ko": "<p><a href=\"/snowboarding-guide/\">스노보드</a>는 동계 스포츠 문화를 변화시켰습니다. 뒷마당 발명품으로 시작된 것이 세계에서 가장 인기 있는 액션 스포츠 중 하나가 되었습니다.</p>"}'::jsonb,
    'historical',
    'SB',
    '{"en": "History of snowboarding - From Sherman Poppen''s Snurfer to Olympic sport, how counter-culture riders transformed winter sports.", "de": "Geschichte des Snowboardens - Vom Snurfer zum olympischen Sport, wie Gegenkultur-Fahrer den Wintersport veränderten.", "fr": "Histoire du snowboard - Du Snurfer de Sherman Poppen au sport olympique, comment les riders contre-culture ont transformé les sports d''hiver.", "it": "Storia dello snowboard - Dallo Snurfer di Sherman Poppen allo sport olimpico, come i rider controculturali hanno trasformato gli sport invernali.", "es": "Historia del snowboard - Del Snurfer de Sherman Poppen al deporte olímpico.", "pt": "História do snowboard - Do Snurfer de Sherman Poppen ao esporte olímpico.", "nl": "Geschiedenis van snowboarden - Van Sherman Poppen''s Snurfer tot olympische sport.", "ar": "تاريخ التزلج على الثلج - من سنورفر شيرمان بوبن إلى الرياضة الأولمبية", "ja": "スノーボードの歴史 - シャーマン・ポッペンのスナーファーからオリンピック競技まで", "zh": "Danbuxue lishi - Cong Sherman Poppen de Snurfer dao Aolinpike yundong", "ko": "스노보드의 역사 - 셔먼 포펜의 스너퍼에서 올림픽 스포츠까지"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
